function imp(f){if(!f)return;if(f.size>25*1024*1024){alert("ব্যাকআপ ফাইল ২৫ MB-এর বেশি হতে পারবে না");return}const r=new FileReader();r.onload=async()=>{try{let d=JSON.parse(r.result);if(d&&d.alg==="AES-GCM")d=await vaultOpen(d);if(!validBackup(d))throw 0;if(!restoreBackupData(d))return;render();alert("রিস্টোর সম্পন্ন")}catch(e){alert("ফাইলটি সঠিক ব্যাকআপ নয়")}};r.readAsText(f)}

function modal(h){closeM();const m=document.createElement("div");m.className="mt";m.id="mt";m.onclick=e=>{if(e.target==m)closeM()};m.innerHTML="<div>"+safeHtml(h)+"</div>";document.body.appendChild(m)}
function closeM(){const m=$("mt");if(m)m.remove()}

