let EN_RE=null;const trCache=new Map(),BN_RE=/[\u0980-\u09FF]/,NT_SKIP=/^(SCRIPT|STYLE|TEXTAREA|NOSCRIPT)$/,TR_ATTR=["placeholder","title","aria-label","alt"];
const ENN={};
function trS(t){
 if(!BN_RE.test(t))return t;
 let r=trCache.get(t);if(r!==undefined)return r;
 if(!EN_RE){for(const k in EN)ENN[k.normalize("NFC")]=EN[k];const ks=Object.keys(ENN).sort((a,b)=>b.length-a.length).map(k=>k.replace(/[.*+?^${}()|[\]\\]/g,"\\$&"));EN_RE=new RegExp("(?<![\\u0980-\\u09FF])(?:"+ks.join("|")+")(?![\\u0980-\\u09FF])","g")}
 r=t.normalize("NFC").replace(EN_RE,m=>ENN[m]).replace(/[০-৯]/g,d=>"০১২৩৪৫৬৭৮৯".indexOf(d));
 if(trCache.size>3000)trCache.clear();trCache.set(t,r);return r}
function trNode(n){
 if(n.nodeType===3){const p=n.parentNode;if(!p||NT_SKIP.test(p.nodeName))return;const v=n.nodeValue;if(!BN_RE.test(v))return;
  if(p.nodeName==="OPTION"&&!p.hasAttribute("value"))p.setAttribute("value",v.replace(/\s+/g," ").trim());
  const t=trS(v);if(t!==v)n.nodeValue=t;return}
 if(n.nodeType!==1||NT_SKIP.test(n.nodeName))return;
 for(const a of TR_ATTR){const v=n.getAttribute(a);if(v&&BN_RE.test(v))n.setAttribute(a,trS(v))}
 for(let c=n.firstChild;c;c=c.nextSibling)trNode(c)}
function trInit(){
 if(LANG!=="en")return;
 document.documentElement.lang="en";document.title=trS(document.title);
 const _a=window.alert,_c=window.confirm,_p=window.prompt;
 window.alert=m=>_a(trS(String(m)));window.confirm=m=>_c(trS(String(m)));window.prompt=(m,d)=>_p(trS(String(m)),d);
 trNode(document.body);
 new MutationObserver(ms=>{for(const m of ms){if(m.type==="characterData")trNode(m.target);else m.addedNodes.forEach(trNode)}}).observe(document.body,{childList:true,subtree:true,characterData:true})}
function setLang(l){if(Store.set.lang==l||(!Store.set.lang&&l=="bn"))return;Store.set.lang=l;save();location.reload()}
initRBAC();migrateExams();autoFees();save();applyTheme();updateNet();render();trInit();lockCheck();setInterval(()=>{if(Store.set.theme=="time"||Store.set.theme=="auto")themeSync()},60000);
if(navigator.onLine&&Store.sync&&Store.sync.apiUrl){setTimeout(syncNow,800);setInterval(()=>{if(navigator.onLine)syncNow()},60000)}
let dip=null;
window.addEventListener("beforeinstallprompt",e=>{e.preventDefault();dip=e});
window.addEventListener("appinstalled",()=>{dip=null;toast("✅ অ্যাপ ইনস্টল হয়েছে")});
if("serviceWorker" in navigator&&/^https?:$/.test(location.protocol)&&!window.Capacitor){navigator.serviceWorker.register("sw.js").then(reg=>{if(reg.waiting)reg.waiting.postMessage({type:"SKIP_WAITING"});mirrorQueueToSw()}).catch(()=>{});navigator.serviceWorker.addEventListener("message",e=>{if(e.data&&e.data.type==="SYNC_COMPLETE"){toast("Background sync সম্পন্ন");syncNow(true)}})}
async function installApp(){
 if(window.matchMedia&&matchMedia("(display-mode: standalone)").matches){toast("আপনি ইতিমধ্যে অ্যাপে আছেন");return}
 if(dip){dip.prompt();try{await dip.userChoice}catch(e){}dip=null;return}
 modal(`<span onclick="closeM()" style="float:right;font-size:22px">×</span><h2>📲 ফোনে ইনস্টল করুন</h2><div style="font-size:14px;line-height:1.9;margin:8px 0">১. Chrome-এ GitHub-এর কোড পেইজ নয়, <b>অ্যাপের লিংক</b> খুলুন:<br><span style="color:var(--pri);word-break:break-all">${APP_URL}</span><br>২. একবার ইন্টারনেটসহ পেইজ পুরো লোড হতে দিন।<br>৩. Chrome-এর ⋮ মেনু → <b>Install app</b> (বা <b>Add to Home screen</b>) চাপুন।</div><button class="btn" style="width:100%" onclick="openExt(APP_URL)">অ্যাপের লিংক খুলুন</button>`)
}
